+		if len(kept) > 0 {
+			verified += len(kept)
+			payload["evidence"] = kept
+			survivors = append(survivors, payload)
+			continue
+		}
+		rejected++
+		delete(payload, "evidence")
+		if mode == EvidenceGateSoft {
+			survivors = append(survivors, payload)
+		}
+	}
+	return survivors, verified, rejected
